(function(){
  if(window.__QMES_RECIPE_CHEM_MASTER__) return;
  window.__QMES_RECIPE_CHEM_MASTER__=true;
  function html(){return `
  <div class="qmes-business-extension qbe-chemical-master">
    <div class="qbe-title-row"><div><h1 class="qbe-title">Recipe / BOM Master</h1><div class="qbe-subtitle">화학 제조 기준으로 제품 Formula, 공정조건, Revision, 승인 및 생산 LOT 이력을 통합 관리합니다.</div></div><button type="button" class="qbe-primary">+ 신규 Revision</button></div>
    <div class="qbe-kpis"><div class="qbe-kpi"><span class="qbe-kpi-label">등록 Recipe</span><b class="qbe-kpi-value">0건</b></div><div class="qbe-kpi orange"><span class="qbe-kpi-label">승인 대기</span><b class="qbe-kpi-value">0건</b></div><div class="qbe-kpi green"><span class="qbe-kpi-label">사용중 Revision</span><b class="qbe-kpi-value">0건</b></div><div class="qbe-kpi red"><span class="qbe-kpi-label">변경 검토</span><b class="qbe-kpi-value">0건</b></div><div class="qbe-kpi slate"><span class="qbe-kpi-label">연결 생산 LOT</span><b class="qbe-kpi-value">0건</b></div></div>
    <div class="qbe-card"><div class="qbe-card-head"><h2>제품 / Recipe 기본정보</h2><span class="qbe-hint">Master Data</span></div><div class="qbe-form-grid"><div class="qbe-field"><label>제품명</label><select><option>선택</option></select></div><div class="qbe-field"><label>제품코드</label><input placeholder="제품코드"></div><div class="qbe-field"><label>고객사</label><select><option>공용 / 선택</option></select></div><div class="qbe-field"><label>제품 Grade</label><input placeholder="Grade / 규격"></div><div class="qbe-field"><label>Recipe No.</label><input placeholder="예: RCP-001"></div><div class="qbe-field"><label>Revision</label><input placeholder="예: Rev.01"></div><div class="qbe-field"><label>기준 Batch Size (kg)</label><input type="number" placeholder="1000"></div><div class="qbe-field"><label>예상 수율 (%)</label><input type="number" step="0.01" placeholder="100.00"></div><div class="qbe-field"><label>적용일</label><input type="date"></div><div class="qbe-field"><label>상태</label><select><option>작성</option><option>검토</option><option>승인</option><option>폐기</option></select></div><div class="qbe-field"><label>작성자</label><input readonly placeholder="로그인 사용자"></div><div class="qbe-field"><label>검토 / 승인</label><input readonly placeholder="전자결재 연동"></div></div></div>
    <div class="qbe-card"><div class="qbe-card-head"><h2>표준 배합표 (Formula)</h2><span class="qbe-hint">배합비 합계 100% 기준</span></div><div class="qbe-table-wrap"><table><thead><tr><th>No</th><th>원료명</th><th>원료코드</th><th>규격 / Grade</th><th>배합비 (%)</th><th>기준 투입량 (kg)</th><th>허용오차 (±%)</th><th>투입순서</th><th>CTQ</th><th>대체원료</th></tr></thead><tbody><tr><td colspan="10" style="text-align:center;color:#94a3b8;padding:24px">등록된 표준 배합 원료가 없습니다.</td></tr></tbody></table></div></div>
    <div class="qbe-split"><div class="qbe-card"><div class="qbe-card-head"><h2>공정조건</h2><span class="qbe-hint">Process Parameter</span></div><div class="qbe-table-wrap"><table><thead><tr><th>공정단계</th><th>설비</th><th>혼합시간</th><th>RPM</th><th>온도</th><th>관리항목</th></tr></thead><tbody><tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:22px">등록된 공정조건이 없습니다.</td></tr></tbody></table></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>품질 / CTQ 연계</h2><span class="qbe-hint">PQC · OQC</span></div><div class="qbe-table-wrap"><table><thead><tr><th>검사항목</th><th>규격</th><th>검사단계</th><th>CTQ</th><th>검사기준 연결</th></tr></thead><tbody><tr><td colspan="5" style="text-align:center;color:#94a3b8;padding:22px">품질 규격을 연결하면 표시됩니다.</td></tr></tbody></table></div></div></div>
    <div class="qbe-split"><div class="qbe-card"><div class="qbe-card-head"><h2>Revision / 변경관리</h2><span class="qbe-hint">4M 변경 연계</span></div><div class="qbe-table-wrap"><table><thead><tr><th>Revision</th><th>적용일</th><th>변경내용</th><th>변경사유</th><th>4M</th><th>승인상태</th></tr></thead><tbody><tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:22px">등록된 개정 이력이 없습니다.</td></tr></tbody></table></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>생산 LOT 적용 이력</h2><span class="qbe-hint">Traceability</span></div><div class="qbe-table-wrap"><table><thead><tr><th>생산일</th><th>생산 LOT</th><th>Revision</th><th>계획량</th><th>실적량</th><th>LOT 추적</th></tr></thead><tbody><tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:22px">해당 Recipe로 생산된 LOT가 없습니다.</td></tr></tbody></table></div></div></div>
    <div class="qbe-card"><div class="qbe-card-head"><h2>MRP / 원가 연계</h2><span class="qbe-hint">Recipe → 생산계획 → 소요량 계산</span></div><div class="qbe-alerts"><div class="qbe-alert blue"><span>Recipe 기준 원료 소요량</span><b>생산계획과 자동 연계</b></div><div class="qbe-alert orange"><span>표준량 대비 실제 투입량</span><b>작업지시 / 작업일지 연계</b></div><div class="qbe-alert blue"><span>표준 Batch 예상 원가</span><b>원료단가 연결 시 계산</b></div></div></div>
  </div>`}
  function patch(){const host=document.getElementById('qmes-business-extension-host');if(!host)return;const title=host.querySelector('.qbe-title,h1');if(!title||!title.textContent.includes('Recipe / BOM Master'))return;if(host.dataset.chemicalRecipePatched==='1')return;host.dataset.chemicalRecipePatched='1';host.innerHTML=html();}
  const ob=new MutationObserver(()=>patch());ob.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest('[data-qbe-menu="recipe"]'))setTimeout(patch,60)},true);setInterval(patch,700);
})();